await story('A8-15-manual-above-automatic-quota',async()=>{
 person('manual').groups=[GROUP_A];const a=await context(cases[0]);await signIn(a.p,'admin','/ui/hub/admin');await a.p.locator('.hub-step-form input').fill('manual');await a.p.locator('.hub-step-form button').click();await a.p.locator('.hub-code').waitFor();const code=(await a.p.locator('.hub-code').innerText()).trim();
 const h=join(scratch,'manual-second-member');mkdirSync(h,{mode:0o700});const second=createHubMemberPairingApi({home:h,enabled:()=>true,link:()=> 'offline',pollMs:250});extraPairings.push(second);fx.fm.attachHubMemberPairing(second);
 const m=await context(cases[0]);await signIn(m.p,'manual','/ui/hub/exposures');const l=await context(cases[0]);const issued=await(await fetch(fx.base+'/auth/issue-code',{method:'POST',headers:{'X-Agend-Token':fx.fm.webToken}})).json();await l.p.goto(fx.base+'/signin');await l.p.fill('#code',issued.code);await l.p.click('#go');await l.p.waitForURL(fx.base+'/ui');await l.p.goto(fx.base+'/settings/hub');await l.p.fill('#hubAddress',memberOrigin);await l.p.fill('#hubCode',code);await l.p.locator('#hub-connect form button[type=submit]').click();await apply(l.p,'.hub-local-confirm');
 await m.p.reload();await m.p.locator('.hub-pairings button').click();await m.p.locator('.dlg-actions .btn-primary').click();await l.p.locator('.hub-local-confirm').click();await apply(l.p,'.hub-local-confirmed, .hub-paired');await a.p.reload();await a.p.getByRole('button',{name:'Approve…',exact:true}).click();await a.p.locator('.dlg-actions .btn-primary').click();await l.p.locator('.hub-paired').waitFor({timeout:20000});check('second manual credential pinned above max=1',second.view().state==='paired');
 await m.p.goto(origin+'/ui/hub');await m.p.locator('[data-welcome=limit]').waitFor();receipt.manualQuotaText=await m.p.locator('[data-welcome=fleets]').innerText();check('two retained manual fleets counted against max one',/2.*1/.test(receipt.manualQuotaText));await shot(m.p,'A8-15-manual-two-of-one');await shot(l.p,'A8-15-second-manual-pinned-offline');
 await l.ctx.close();await m.ctx.close();await a.ctx.close();fx.fm.attachHubMemberPairing(globalThis.a8Expiry.ep);
});
await story('A8-15-ineligible-manual-refused',async()=>{
 const a=await context(cases[0]);await signIn(a.p,'admin','/ui/hub/admin');person('negative').eligible=false;await a.p.locator('.hub-step-form input').fill('negative');const response=a.p.waitForResponse(r=>new URL(r.url()).pathname==='/hub/v1/admin/pairings'&&r.request().method()==='POST');await a.p.locator('.hub-step-form button').click();const r=await response;receipt.ineligibleOffer={status:r.status(),body:await r.json()};check('ineligible owner receives no offer',!r.ok());await shot(a.p,'A8-15-ineligible-refused');person('negative').eligible=true;await a.ctx.close();
});
